<!DOCTYPE html>
<html lang="en" dir="ltr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Summit Online School gives every learner a clear, connected path forward.">
    <title>Summit Online School | Learn with confidence</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet">
    <script>document.documentElement.classList.add('has-js');</script>
    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <style>
        :root { --green:#0c7261; --green-dark:#064a3f; --green-deep:#043b33; --yellow:#f8eb2f; --paper:#f8f7f1; --cream:#efeee7; --ink:#122722; --muted:#61706b; --line:#d7ded9; --white:#fff; --coral:#f0644d; --mint:#bce6d5; }
        * { box-sizing:border-box; }
        html { scroll-behavior:smooth; }
        body.landing-page { background:var(--paper); color:var(--ink); font-family:'DM Sans',Arial,sans-serif; margin:0; overflow-x:hidden; }
        .landing-page h1,.landing-page h2,.landing-page h3,.landing-page p { margin-top:0; }
        .landing-page a { color:inherit; text-decoration:none; }
        .landing-page button,.landing-page input,.landing-page textarea { font:inherit; }
        .skip-link { background:var(--yellow); color:var(--ink); font-weight:800; left:1rem; padding:.75rem 1rem; position:fixed; top:-4rem; transition:top .2s; z-index:100; }
        .skip-link:focus { top:1rem; }
        .page-width { margin:0 auto; max-width:1200px; padding-left:28px; padding-right:28px; }
        .site-header { background:rgba(248,247,241,.94); border-bottom:1px solid rgba(12,114,97,.12); position:sticky; top:0; z-index:30; backdrop-filter:blur(15px); }
        .nav-shell { align-items:center; display:flex; gap:28px; height:76px; justify-content:space-between; }
        .brand { align-items:center; display:inline-flex; font-family:'Manrope',sans-serif; font-size:1rem; font-weight:800; gap:10px; letter-spacing:-.045em; line-height:1.05; min-width:170px; }
        .brand-mark { background:#fff; border:1px solid #d7ded9; border-radius:50%; display:grid; height:48px; overflow:hidden; place-items:center; width:48px; }
        .brand-mark img { height:41px; object-fit:contain; width:41px; }
        .brand span:last-child { color:var(--green); display:block; font-size:.67rem; letter-spacing:.1em; margin-top:3px; text-transform:uppercase; }
        .nav-links { align-items:center; display:flex; gap:24px; margin-left:auto; }
        .nav-links a { color:#37524a; font-size:.78rem; font-weight:800; letter-spacing:.025em; padding:9px 0; position:relative; text-transform:uppercase; }
        .nav-links a::after { background:var(--green); bottom:3px; content:''; height:2px; left:0; position:absolute; transform:scaleX(0); transform-origin:left; transition:transform .2s; width:100%; }
        .nav-links a:hover::after,.nav-links a:focus-visible::after { transform:scaleX(1); }
        .nav-actions { align-items:center; display:flex; gap:16px; }
        .login-link { color:var(--green); font-size:.82rem; font-weight:800; }
        .pill { align-items:center; border:1px solid transparent; border-radius:999px; display:inline-flex; font-size:.78rem; font-weight:800; gap:8px; justify-content:center; letter-spacing:.015em; min-height:43px; padding:0 19px; transition:transform .18s,background .18s,box-shadow .18s; }
        .pill:hover { transform:translateY(-2px); }
        .pill-primary { background:var(--green); box-shadow:0 7px 0 rgba(4,59,51,.15); color:#fff; }
        .pill-primary:hover { background:var(--green-dark); }
        .pill-yellow { background:var(--yellow); box-shadow:0 7px 0 rgba(47,51,8,.2); color:var(--ink); }
        .pill-yellow:hover { background:#e9dc28; }
        .pill-outline { border-color:rgba(255,255,255,.6); color:#fff; }
        .pill-outline:hover { background:#fff; color:var(--green-deep); }
        .pill svg { height:15px; width:15px; }
        .nav-toggle { background:#fff; border:1px solid var(--line); border-radius:9px; color:var(--green-deep); cursor:pointer; display:none; height:40px; padding:0; width:40px; }
        .nav-toggle svg { height:21px; width:21px; }
        .hero { padding:13px 0 0; }
        .hero-frame { background:var(--green-deep); border-radius:0 0 30px 30px; color:#fff; min-height:575px; overflow:hidden; position:relative; }
        .hero-frame::before { background:linear-gradient(115deg,rgba(4,59,51,.36),transparent 58%); content:''; inset:0; position:absolute; z-index:1; }
        .hero-frame::after { border:1px solid rgba(248,235,47,.35); border-radius:50%; content:''; height:430px; position:absolute; right:-185px; top:-145px; width:430px; }
        .hero-grid { align-items:center; display:grid; grid-template-columns:.84fr 1.16fr; min-height:575px; position:relative; z-index:2; }
        .hero-copy { padding:75px 0 82px; position:relative; z-index:3; }
        .overline { align-items:center; color:var(--yellow); display:flex; font-size:.7rem; font-weight:800; gap:8px; letter-spacing:.12em; margin-bottom:17px; text-transform:uppercase; }
        .overline::before { background:var(--yellow); content:''; height:2px; width:26px; }
        .hero h1 { font-family:'Manrope',sans-serif; font-size:clamp(2.9rem,5.2vw,5.15rem); font-weight:800; letter-spacing:-.07em; line-height:.92; margin-bottom:22px; max-width:560px; text-transform:uppercase; }
        .hero h1 strong { color:var(--yellow); font:inherit; }
        .hero-copy p { color:#d0e1da; font-size:1.04rem; line-height:1.7; margin-bottom:30px; max-width:470px; }
        .hero-buttons { display:flex; flex-wrap:wrap; gap:12px; }
        .hero-note { align-items:center; color:#c3d6cf; display:flex; font-size:.76rem; font-weight:700; gap:9px; margin-top:35px; }
        .hero-note i { background:var(--yellow); border-radius:50%; color:var(--green-deep); display:grid; font-style:normal; height:24px; place-items:center; width:24px; }
        .hero-visual { align-self:stretch; min-height:510px; overflow:hidden; position:relative; }
        .hero-sun { background:var(--yellow); border-radius:50%; height:285px; opacity:.96; position:absolute; right:75px; top:88px; width:285px; }
        .hero-pattern { background-image:radial-gradient(rgba(255,255,255,.2) 1px,transparent 1px); background-size:17px 17px; height:180px; position:absolute; right:15px; top:75px; transform:rotate(12deg); width:185px; }
        .school-scene { bottom:0; height:420px; position:absolute; right:0; width:100%; }
        .school-scene .ground { background:#08342c; bottom:0; height:73px; left:0; position:absolute; right:0; }
        .school-scene .building { background:#f5edcf; bottom:56px; box-shadow:inset -16px 0 rgba(12,114,97,.16); height:252px; position:absolute; right:7%; width:54%; }
        .school-scene .building::before { background:var(--green); bottom:0; content:''; height:82px; left:40%; position:absolute; width:70px; }
        .school-scene .building::after { background:repeating-linear-gradient(90deg,#277d6f 0 24px,transparent 24px 47px); content:''; height:85px; left:31px; position:absolute; top:42px; width:72%; }
        .school-scene .roof { border-bottom:38px solid #e2be50; border-left:72px solid transparent; border-right:72px solid transparent; height:0; position:absolute; right:1%; top:75px; width:60%; }
        .school-scene .tower { background:#e9c85d; bottom:56px; height:310px; position:absolute; right:60%; width:105px; }
        .school-scene .tower::before { border-bottom:44px solid #e9c85d; border-left:53px solid transparent; border-right:53px solid transparent; content:''; position:absolute; top:-44px; }
        .school-scene .tower::after { background:repeating-linear-gradient(90deg,#277d6f 0 18px,transparent 18px 32px); content:''; height:56px; left:18px; position:absolute; top:47px; width:70px; }
        .student { bottom:53px; position:absolute; z-index:3; }
        .student .leg { background:#233d3a; bottom:0; height:90px; position:absolute; width:23px; }
        .student .leg.one { left:28px; transform:rotate(4deg); }.student .leg.two { left:56px; transform:rotate(-4deg); }
        .student .body { background:#f7f7f2; border:5px solid #0b2f2a; border-radius:34px 34px 15px 15px; bottom:75px; height:117px; position:absolute; width:93px; }
        .student .body::after { background:var(--yellow); border-radius:0 0 50% 50%; content:''; height:32px; left:13px; position:absolute; top:0; width:58px; }
        .student .head { background:#9a623e; border-radius:45% 45% 42% 42%; bottom:174px; height:73px; left:16px; position:absolute; width:61px; }
        .student .hair { background:#38251c; border-radius:45% 45% 18px 18px; bottom:219px; height:30px; left:11px; position:absolute; width:72px; z-index:1; }
        .student .bag { background:var(--green); border:4px solid #082f29; border-radius:12px 12px 18px 18px; bottom:95px; height:77px; position:absolute; right:-21px; transform:rotate(-8deg); width:44px; }
        .student-one { left:11%; transform:scale(1.06); }.student-two { left:38%; transform:scale(.85); transform-origin:bottom; }.student-three { right:8%; transform:scale(.78); transform-origin:bottom; }
        .student-two .head { background:#d49b75; }.student-two .hair { background:#211d1b; }.student-two .body { background:#cee8dd; }.student-two .bag { background:var(--yellow); }
        .student-three .head { background:#6e402b; }.student-three .hair { background:#24190f; border-radius:50% 50% 30% 30%; height:38px; }.student-three .body { background:#fff; }.student-three .bag { background:var(--coral); }
        .hero-stamp { align-items:center; background:var(--yellow); border:2px solid var(--green-deep); border-radius:50%; bottom:44px; color:var(--green-deep); display:flex; flex-direction:column; font-family:'Manrope',sans-serif; font-size:.59rem; font-weight:800; height:92px; justify-content:center; line-height:1.1; position:absolute; right:42%; text-align:center; transform:rotate(10deg); width:92px; z-index:5; }
        .hero-stamp b { display:block; font-size:1.5rem; letter-spacing:-.08em; }
        .intro { padding:105px 0 95px; }
        .split-intro { align-items:center; display:grid; gap:78px; grid-template-columns:.9fr 1fr; }
        .section-label { color:var(--green); font-size:.68rem; font-weight:800; letter-spacing:.12em; margin-bottom:12px; text-transform:uppercase; }
        .section-title { font-family:'Manrope',sans-serif; font-size:clamp(2.15rem,3.6vw,3.65rem); font-weight:800; letter-spacing:-.065em; line-height:.98; margin-bottom:18px; text-transform:uppercase; }
        .section-title .accent { color:var(--green); }
