        .mini-value span { color:var(--muted); font-size:.77rem; line-height:1.45; }
        .classroom { background:var(--green); border-radius:18px; box-shadow:17px 17px 0 #d8e5dc; height:375px; overflow:hidden; position:relative; }
        .classroom::before { background:linear-gradient(90deg,rgba(255,255,255,.1) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.1) 1px,transparent 1px); background-size:24px 24px; content:''; inset:0; opacity:.7; position:absolute; }
        .classroom-window { background:#bee9e7; border:7px solid #f7e557; border-radius:6px; height:176px; position:absolute; right:30px; top:30px; width:176px; }
        .classroom-window::before,.classroom-window::after { background:#f7e557; content:''; position:absolute; }
        .classroom-window::before { height:7px; left:0; top:78px; width:100%; }.classroom-window::after { height:100%; left:78px; top:0; width:7px; }
        .board { background:#0a4f43; border:7px solid #f0d57a; bottom:33px; height:146px; left:31px; position:absolute; transform:rotate(-3deg); width:68%; }
        .board::before { border:2px solid #c8ece0; border-radius:50%; content:''; height:63px; left:24px; position:absolute; top:32px; width:100px; }.board::after { background:repeating-linear-gradient(#c8ece0 0 3px,transparent 3px 19px); height:72px; position:absolute; right:24px; top:34px; width:82px; }
        .classroom-kid { bottom:20px; position:absolute; right:31px; z-index:3; }.classroom-kid .head { background:#875438; border-radius:50%; height:70px; left:21px; position:absolute; top:0; width:70px; }.classroom-kid .hair { background:#241b17; border-radius:55% 55% 25% 25%; height:37px; left:15px; position:absolute; top:-9px; width:82px; }.classroom-kid .shirt { background:var(--yellow); border-radius:48px 48px 12px 12px; height:118px; left:0; position:absolute; top:57px; width:112px; }.classroom-kid .book { background:#fff; border:3px solid #164d45; height:48px; left:-25px; position:absolute; top:107px; transform:rotate(15deg); width:72px; }
        .why { background:#10231f; color:#fff; padding:98px 0 104px; }
        .why-head { align-items:end; display:flex; justify-content:space-between; margin-bottom:35px; }
        .why .section-label { color:var(--yellow); }.why .section-title { margin-bottom:0; max-width:610px; }
        .why-note { color:#afc5bd; font-size:.87rem; line-height:1.6; max-width:270px; }
        .reason-grid { display:grid; gap:15px; grid-template-columns:repeat(4,1fr); }
        .reason-card { background:#1a3430; border-radius:12px; min-height:255px; overflow:hidden; padding:16px; position:relative; }
        .reason-picture { background:var(--mint); border-radius:8px; height:155px; margin-bottom:16px; overflow:hidden; position:relative; }
        .reason-picture::after { border:4px solid rgba(12,114,97,.34); border-radius:50%; content:''; height:120px; position:absolute; right:-24px; top:22px; width:120px; }
        .reason-picture.b { background:#e7d98c; }.reason-picture.c { background:#e8b9a3; }.reason-picture.d { background:#b3d8e5; }
        .reason-picture svg { bottom:14px; color:var(--green); height:112px; left:18px; position:absolute; width:112px; z-index:1; }
        .reason-card small { color:var(--yellow); font-size:.61rem; font-weight:800; letter-spacing:.1em; text-transform:uppercase; }.reason-card h3 { font-family:'Manrope',sans-serif; font-size:1.02rem; letter-spacing:-.04em; margin:5px 0 0; text-transform:uppercase; }
        .contact-links { padding:102px 0 68px; }
        .links-heading { max-width:500px; }.links-heading .section-title { margin-bottom:0; }
        .quick-grid { display:grid; gap:14px; grid-template-columns:repeat(4,1fr); margin-top:37px; }
        .quick-card { background:#fff; border:1px solid #e3e5df; border-radius:13px; box-shadow:0 7px 20px rgba(10,50,43,.06); min-height:188px; padding:20px; transition:transform .2s,box-shadow .2s; }
        .quick-card:hover { box-shadow:0 15px 26px rgba(10,50,43,.11); transform:translateY(-5px); }.quick-card.featured { background:var(--green); color:#fff; }
        .quick-icon { align-items:center; background:#dff2e9; border-radius:9px; color:var(--green); display:flex; height:36px; justify-content:center; margin-bottom:25px; width:36px; }.featured .quick-icon { background:var(--yellow); color:var(--green-deep); }.quick-icon svg { height:19px; width:19px; }
        .quick-card h3 { font-family:'Manrope',sans-serif; font-size:.94rem; letter-spacing:-.04em; margin-bottom:7px; text-transform:uppercase; }.quick-card p { color:var(--muted); font-size:.75rem; line-height:1.55; margin-bottom:15px; }.quick-card.featured p { color:#c8e2d8; }
        .quick-card a { color:var(--green); font-size:.68rem; font-weight:800; text-transform:uppercase; }.quick-card.featured a { color:var(--yellow); }
        .ribbon { background:var(--yellow); color:var(--green-deep); display:flex; font-family:'Manrope',sans-serif; font-size:.78rem; font-weight:800; gap:43px; letter-spacing:.025em; margin:18px 0 0; overflow:hidden; padding:17px 0; text-transform:uppercase; transform:rotate(-1.65deg) scale(1.03); white-space:nowrap; }
        .ribbon span { align-items:center; display:inline-flex; gap:43px; }.ribbon i { background:var(--green); border-radius:50%; display:inline-block; height:7px; width:7px; }
        .program-section { padding:105px 0; }.program-intro { align-items:end; display:flex; justify-content:space-between; margin-bottom:38px; }.program-intro .section-title { margin-bottom:0; max-width:650px; }.program-intro p { color:var(--muted); font-size:.86rem; line-height:1.65; margin:0; max-width:300px; }
        .stage-tabs { border-bottom:1px solid #cdd8d2; display:flex; gap:0; margin-bottom:33px; }.stage-tabs span { color:#71807b; flex:1; font-size:.68rem; font-weight:800; padding:0 0 14px; position:relative; text-align:center; text-transform:uppercase; }.stage-tabs span.active { color:var(--green); }.stage-tabs span.active::after { background:var(--green); bottom:-2px; content:''; height:4px; left:23%; position:absolute; width:54%; }
        .program-spotlight { align-items:center; display:grid; gap:52px; grid-template-columns:1fr .94fr; }.program-gallery { display:grid; gap:12px; grid-template-columns:1.35fr 1fr; height:296px; }.program-scene { background:#efd977; border-radius:13px; overflow:hidden; position:relative; }.program-scene::before { background:var(--green); border-radius:22px 22px 0 0; bottom:0; content:''; height:55%; left:18%; position:absolute; width:56%; }.program-scene::after { background:#fff; border:5px solid #d9bd57; border-radius:50%; content:''; height:105px; position:absolute; right:10%; top:12%; width:105px; }.gallery-small { display:grid; gap:12px; grid-template-rows:1fr 1fr; }.gallery-small div { border-radius:13px; overflow:hidden; position:relative; }.gallery-small div:first-child { background:#bbdcd4; }.gallery-small div:last-child { background:#f0ad8d; }.gallery-small div::before { background:var(--green); border-radius:50% 50% 8px 8px; bottom:-22px; content:''; height:110px; left:28%; position:absolute; width:73px; }.gallery-small div::after { background:#74472e; border-radius:50%; content:''; height:56px; left:35%; position:absolute; top:22%; width:56px; }
        .program-copy h3 { font-family:'Manrope',sans-serif; font-size:clamp(1.7rem,3vw,2.8rem); letter-spacing:-.065em; line-height:1; margin-bottom:15px; text-transform:uppercase; }.program-copy p { color:var(--muted); font-size:.88rem; line-height:1.72; }.program-copy .pill { margin-top:15px; }
        .calendar-section { background:#e8eee9; padding:96px 0 103px; }.calendar-card { background:#fff; border-radius:19px; box-shadow:0 17px 38px rgba(4,59,51,.12); display:grid; grid-template-columns:150px 1fr 240px; margin-top:40px; min-height:295px; overflow:hidden; }.calendar-months { background:var(--green); color:#dcefe8; display:flex; flex-direction:column; gap:9px; padding:22px; }.calendar-months strong { color:#fff; font-family:'Manrope',sans-serif; font-size:1rem; margin-bottom:3px; }.calendar-months span { font-size:.67rem; }.calendar-months span.active { background:var(--yellow); border-radius:5px; color:var(--green-deep); font-weight:800; margin:0 -7px; padding:5px 7px; }.calendar-main { padding:26px 30px; }.calendar-main h3 { font-family:'Manrope',sans-serif; font-size:1.2rem; letter-spacing:-.05em; margin-bottom:24px; text-transform:uppercase; }.weekdays,.calendar-days { display:grid; grid-template-columns:repeat(7,1fr); text-align:center; }.weekdays { color:#8a9691; font-size:.62rem; font-weight:800; margin-bottom:13px; }.calendar-days { gap:10px 4px; }.calendar-days span { align-items:center; border-radius:50%; display:flex; font-size:.7rem; height:27px; justify-content:center; margin:auto; width:27px; }.calendar-days span.event { background:var(--yellow); color:var(--green-deep); font-weight:800; }.calendar-days span.today { background:var(--green); color:#fff; font-weight:800; }.calendar-side { background:#fafcfb; border-left:1px solid #e5e9e6; padding:27px 22px; }.calendar-side h3 { color:var(--green); font-family:'Manrope',sans-serif; font-size:.91rem; letter-spacing:-.04em; margin-bottom:18px; text-transform:uppercase; }.event-row { align-items:flex-start; display:flex; gap:10px; margin:0 0 16px; }.event-row i { background:var(--coral); border-radius:50%; display:block; flex:0 0 auto; height:8px; margin-top:4px; width:8px; }.event-row:nth-of-type(3) i { background:var(--yellow); }.event-row:nth-of-type(4) i { background:var(--green); }.event-